178: // function to write binaries of OpenCL compiled program
179: // binaries are written as separate files for each device
180: // with file name "(program_file_name)_(name of device).bin"
181: // based on variant of Logan
182: // http://logan.tw/posts/2014/11/22/pre-compile-the-opencl-kernel-program-part-2/
183: UTILS_EXPORT
184: cl_int cl_util_write_binaries(const cl_program program,
185:                               const char *const program_file_name)
186: {
187:     cl_int error = CL_SUCCESS;
188: 
189:     cl_uint num_devices = 0;
190:     size_t binaries_size_alloc_size = 0;
191:     size_t binaries_ptr_alloc_size = 0;
192:     size_t *binaries_size = NULL;
193:     unsigned char **binaries_ptr = NULL;
194:     cl_device_id *devices = NULL;
195: 
196:     // read number of devices
197:     OCLERROR_RET(clGetProgramInfo(program, CL_PROGRAM_NUM_DEVICES,
198:                                   sizeof(cl_uint), &num_devices, NULL),
199:                  error, end);
200:     if (num_devices == 0) return CL_INVALID_PROGRAM_EXECUTABLE;
201: 
202:     // read the binaries size
203:     binaries_size_alloc_size = sizeof(size_t) * num_devices;
204:     MEM_CHECK(binaries_size = (size_t *)malloc(binaries_size_alloc_size), error,
205:               end);
206: 
207:     OCLERROR_RET(clGetProgramInfo(program, CL_PROGRAM_BINARY_SIZES,
208:                                   binaries_size_alloc_size, binaries_size,
209:                                   NULL),
210:                  error, end);
211: 
212:     // read the binaries
213:     binaries_ptr_alloc_size = sizeof(unsigned char *) * num_devices;
214:     MEM_CHECK(binaries_ptr = (unsigned char **)malloc(binaries_ptr_alloc_size),
215:               error, end);
216:     memset(binaries_ptr, 0, binaries_ptr_alloc_size);
217: 
218:     for (cl_uint i = 0; i < num_devices; ++i)
219:         MEM_CHECK(binaries_ptr[i] = (unsigned char *)malloc(binaries_size[i]),
220:                   error, end);
221: 
222:     OCLERROR_RET(clGetProgramInfo(program, CL_PROGRAM_BINARIES,
223:                                   binaries_ptr_alloc_size, binaries_ptr, NULL),
224:                  error, end);
225: 
226:     // query devices
227:     MEM_CHECK(devices =
228:                   (cl_device_id *)malloc(sizeof(cl_device_id) * num_devices),
229:               error, end);
230:     OCLERROR_RET(clGetProgramInfo(program, CL_PROGRAM_DEVICES,
231:                                   sizeof(cl_device_id) * num_devices, devices,
232:                                   NULL),
233:                  error, end);
234: 
235:     // write the binaries to files
236:     for (cl_uint i = 0; i < num_devices; ++i)
237:     {
238:         // get device name
239:         char name_data[201];
240:         OCLERROR_RET(clGetDeviceInfo(devices[i], CL_DEVICE_NAME,
241:                                      sizeof(name_data) - 1, name_data, NULL),
242:                      error, end);
243:         name_data[200] = '\0';
244:         // create output file name
245:         char filename[256];
246:         snprintf(filename, sizeof(filename), "%s-%s.bin", program_file_name,
247:                  name_data);
248: 
249:         // write the binary to the output file
250:         FILE *f = NULL;
251:         if (fopen_s(&f, filename, "wb") == 0)
252:         {
253:             if (fwrite(binaries_ptr[i], sizeof(unsigned char), binaries_size[i],
254:                        f)
255:                 != binaries_size[i])
256:                 error = CL_UTIL_FILE_OPERATION_ERROR;
257:             fclose(f);
258:         }
259:         else
260:             error = CL_INVALID_VALUE;
261:     }
262: 
263: end: // cleanup
264:     if (binaries_ptr != NULL)
265:     {
266:         for (cl_uint i = 0; i < num_devices; ++i) free(binaries_ptr[i]);
267:         free(binaries_ptr);
268:     }
269:     free(binaries_size);
270: 
271:     return error;
272: }
