13: uint32_t pcg32_random_r(pcg32_random_t* rng)
14: {
15:     uint64_t oldstate = rng->state;
16:     // Advance internal state
17:     rng->state = oldstate * 6364136223846793005ULL + (rng->inc | 1);
18:     // Calculate output function (XSH RR), uses old state for max ILP
19:     uint32_t xorshifted = (uint32_t)(((oldstate >> 18u) ^ oldstate) >> 27u);
20:     uint32_t rot = oldstate >> 59u;
21:     return (xorshifted >> rot) | (xorshifted << ((0 - rot) & 31));
22: }
