28:     Image read_image(const char* const file_name, cl_int* const error = nullptr)
29:     {
30:         cl_int err = CL_SUCCESS;
31: 
32:         Image im;
33:         unsigned char* data =
34:             stbi_load(file_name, &im.width, &im.height, &im.pixel_size, 0);
35: 
36:         if (data == nullptr)
37:         {
38:             std::string err_msg{ "Not possible to read file" };
39:             const char* load_msg = stbi_failure_reason();
40: 
41:             if (load_msg) err_msg += std::string(": ") + load_msg;
42: 
43:             cl::util::detail::errHandler(CL_INVALID_ARG_VALUE, &err,
44:                                          err_msg.c_str());
45:         }
46: 
47:         std::size_t data_size = im.width * im.height * im.pixel_size;
48: 
49:         im.pixels.insert(im.pixels.end(), data, data + data_size);
50: 
51:         if (im.width && im.height && im.pixel_size
52:             && im.pixels.size() == data_size)
53:             err = CL_SUCCESS;
54:         else
55:             cl::util::detail::errHandler(CL_INVALID_ARG_VALUE, &err,
56:                                          "File read error!");
57: 
58:         if (error != nullptr) *error = err;
59:         return im;
60:     }
