62:     cl_int write_image(const char* file_name, const Image& image)
63:     {
64:         cl_int error = CL_SUCCESS;
65: 
66: #if __cplusplus >= 201703L
67:         std::filesystem::path fn(file_name);
68:         std::string extension = fn.extension().string();
69: #else
70:         const char* extpos = strrchr(file_name, '.');
71:         if (extpos == nullptr)
72:             cl::util::detail::errHandler(CL_INVALID_ARG_VALUE, &error,
73:                                          "No file extension!");
74:         std::string extension(extpos);
75: #endif
76: 
77:         // solution by Timmmm https://stackoverflow.com/questions/11635
78:         auto str_compare = [](const string& a, const string& b) {
79:             return std::equal(
80:                 a.begin(), a.end(), b.begin(), b.end(),
81:                 [](char a, char b) { return tolower(a) == tolower(b); });
82:         };
83: 
84:         if (str_compare(extension, ".png"))
85:         {
86:             if (!stbi_write_png(file_name, image.width, image.height,
87:                                 image.pixel_size, image.pixels.data(), 0))
88:                 cl::util::detail::errHandler(CL_INVALID_ARG_VALUE, &error,
89:                                              "Not possible to write PNG file!");
90:         }
91:         else if (str_compare(extension, ".bmp"))
92:         {
93:             if (!stbi_write_bmp(file_name, image.width, image.height,
94:                                 image.pixel_size, image.pixels.data()))
95:                 cl::util::detail::errHandler(CL_INVALID_ARG_VALUE, &error,
96:                                              "Not possible to write BMP file!");
97:         }
98:         else if (str_compare(extension, ".jpg"))
99:         {
100:             if (!stbi_write_jpg(file_name, image.width, image.height,
101:                                 image.pixel_size, image.pixels.data(), 80))
102:                 cl::util::detail::errHandler(CL_INVALID_ARG_VALUE, &error,
103:                                              "Not possible to write JPG file!");
104:         }
105:         else
106:             cl::util::detail::errHandler(CL_IMAGE_FORMAT_NOT_SUPPORTED, &error,
107:                                          "Unknown file extension!");
108: 
109:         return error;
110:     }
111: }
